// Generated by tyra-editor from the Flow Graph. Do not edit -
// regenerated on every build. Edit the graph in the editor instead.
#include "scripts/script.hpp"

namespace Script_demo {

class FlowGraphScript : public Script {
 public:
  void update(ScriptContext& ctx) override {
    frame++;
    if (!started) {
      started = true;
      ctx.skyColor = Tyra::Color(0.0F, 0.0F, 0.0F);
    }
  }

 private:
  int frame = 0;
  bool started = false;
};

}  // namespace Script_demo

TYRA_SCRIPT(Script_demo::FlowGraphScript);
